package org.example.saildroid.media;
import android.app.Activity;import android.os.Bundle;import android.os.Handler;import android.graphics.SurfaceTexture;import android.view.*;import android.widget.*;import android.media.MediaPlayer;import javax.net.ssl.*;import java.security.*;import java.security.cert.*;import java.util.*;
public final class MediaActivity extends Activity implements TextureView.SurfaceTextureListener {
 MediaPlayer player;Surface surface;int errors=0,prepared=0,stage=0;Handler handler=new Handler();TextView status;SSLSocketFactory original;
 void log(String s){System.err.println("MEDIA_TLS_PROBE="+s);status.setText(s);}
 public void onCreate(Bundle b){super.onCreate(b);try{original=HttpsURLConnection.getDefaultSSLSocketFactory();KeyStore store=KeyStore.getInstance(KeyStore.getDefaultType());store.load(null,null);try(java.io.InputStream in=getAssets().open("server.crt")){store.setCertificateEntry("fixture",CertificateFactory.getInstance("X.509").generateCertificate(in));}TrustManagerFactory trust=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());trust.init(store);SSLContext context=SSLContext.getInstance("TLS");context.init(null,trust.getTrustManagers(),null);HttpsURLConnection.setDefaultSSLSocketFactory(context.getSocketFactory());}catch(Exception e){throw new RuntimeException(e);}LinearLayout box=new LinearLayout(this);box.setOrientation(1);status=new TextView(this);box.addView(status,new LinearLayout.LayoutParams(-1,200));TextureView view=new TextureView(this);view.setSurfaceTextureListener(this);box.addView(view,new LinearLayout.LayoutParams(-1,1200));setContentView(box);android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);int focus=audio.requestAudioFocus(change->{},android.media.AudioManager.STREAM_MUSIC,android.media.AudioManager.AUDIOFOCUS_GAIN);if(focus!=0)throw new AssertionError("Unexpected Android focus grant");log("focus_denied|result="+focus);log("created");}
 void attempt(){try{if(stage==2)HttpsURLConnection.setDefaultSSLSocketFactory(original);player=new MediaPlayer();player.setSurface(surface);player.setOnPreparedListener(mp->{prepared++;log("prepared|stage="+stage);mp.start();});player.setOnCompletionListener(mp->{log("eos|stage="+stage);mp.release();player=null;stage++;handler.postDelayed(this::attempt,150);});player.setOnErrorListener((mp,a,b)->{log("error|stage="+stage+"|what="+a+"|extra="+b);errors++;mp.release();player=null;stage++;if(stage<3)handler.postDelayed(this::attempt,150);else{HttpsURLConnection.setDefaultSSLSocketFactory(original);log("passed|errors="+errors+"|prepared="+prepared);}return true;});Map<String,String> headers=new LinkedHashMap<>();headers.put("X-SaiDroid-Media","312");headers.put("Host",stage==1?"wrong.invalid":"localhost");player.setDataSource("https://127.0.0.1:9443/clip.webm",headers);player.prepareAsync();log("requested|stage="+stage);}catch(Throwable e){log("exception|"+e);e.printStackTrace();}}
 public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){surface=new Surface(t);attempt();}
 public boolean onSurfaceTextureDestroyed(SurfaceTexture t){if(player!=null)player.release();if(surface!=null)surface.release();HttpsURLConnection.setDefaultSSLSocketFactory(original);return true;}
 public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){}public void onSurfaceTextureUpdated(SurfaceTexture t){}
}
